# build_fig_3_5_professionalisation_composite.R
#
# Figure 3.5 — professionalisation of the political class, 1979-2023. Four
# RENUMBERED 12 Sep 2026 from Figure 3.2 to 3.5 (moved to lead into the path
# analysis as the surviving candidate, after the values-evidence figures).
# stacked panels rather than one overlaid panel: PJ asked why not overlay the
# three raw components with the composite. Checked directly — the three
# normalized components correlate at r=0.89-0.95 (mean gap 0.155 on a 0-1
# scale), so an overlay would mostly read as one line, obscuring both the
# "these move together" story and the one place they don't (staffing spend
# visibly lags the other two, 1996-2004). Same stacked-panel pattern as
# fig_2_6_electoral_volatility.R (Ch2 house convention) for correlated-but-
# distinct component series.
#   A. Career politicians (% of MPs)
#   B. Special advisers (SPADs) in post
#   C. MP staffing spend, real terms (2015 prices)
#   D. Composite index (PC1)
#
# House style: sources figure_house_theme.R — greyscale, hard-boiled title,
# descriptive-only subtitles, sources off the figure.
#
# OUTPUT: figures/fig_3_5_professionalisation_composite.png

suppressMessages({library(dplyr); library(readr); library(ggplot2); library(tibble); library(patchwork)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

# ============================================================
# 1. REBUILD PROFESSIONALISATION PC1 — identical construction to 41e-41j
# ============================================================
norm01 <- function(x) (x - min(x, na.rm = TRUE)) / (max(x, na.rm = TRUE) - min(x, na.rm = TRUE))
YEARS  <- 1979:2025
# Extended from 2023, 5 Sep 2026 — the 2023 cutoff below was stale, not a real
# data limit: SPADs has real data through 2025, IPSA staffing through 2024
# (2025 carry-forward, same method already used for career_pct throughout).
# N=47 to match the trust/speech series ranges elsewhere in Ch3.

career_obs <- bind_rows(
  tribble(~year, ~pct, 1979, 3.0, 1983, 4.5, 2010, 14.0, 2015, 17.0, 2019, 21.0),
  # Henn (2018) Table 6, "Politician/Pol Organiser" row — his own narrower
  # category, same definition as Criddle's, reported directly by election
  # year, no calibration needed. Must match 41_career_politicians.R exactly.
  # (Fixed 4 Sep: previously used the broader "Westminster Group" row minus a
  # 6.7pp calibration adjustment — PJ: "keep to Criddle throughout and use
  # Henn to get there." Before that, 3 Sep fix was a wrong pct_wg tribble
  # entirely — see script history.)
  tribble(~year, ~pct, 1987, 5.4, 1992, 7.3, 1997, 9.5, 2001, 10.5, 2005, 14.1)
) |> arrange(year)

career_annual <- tibble(year = YEARS) |>
  mutate(obs_yr     = sapply(year, function(y) max(career_obs$year[career_obs$year <= y])),
         career_pct = career_obs$pct[match(obs_yr, career_obs$year)])

spads <- read_csv(file.path(PROJECT, "data/raw/spads_DATA_ENTRY.csv"),
                  show_col_types = FALSE) |> filter(year <= 2025)
spads_annual <- tibble(year = YEARS,
  n_spads = approx(spads$year, spads$n_spads, xout = YEARS, rule = 2)$y)

ipsa  <- read_csv(file.path(PROJECT, "data/processed/ipsa_staffing_annual.csv"),
                  show_col_types = FALSE) |> select(cal_year, staffing_real = mean_staffing_real_2015)
# REPOINTED 7 Sep 2026: real Butler & Butler (2011) maxima calibrated against
# the true IPSA 2012-2016 overlap ratio (0.854 mean), replacing the flat-85%-
# assumption placeholder. See 41m_staffing_calibrate_butler.R. 1991 has no
# source figure (confirmed genuine gap) and is dropped, same as 41e.
pre10 <- read_csv(file.path(PROJECT, "data/processed/staffing_pre2010_calibrated_butler.csv"),
                  show_col_types = FALSE) |> filter(!is.na(real_2015_mean)) |>
  select(cal_year = year, staffing_real = real_2015_mean)
staffing_obs <- bind_rows(pre10, ipsa) |> arrange(cal_year) |> filter(cal_year <= 2025)
staffing_annual <- tibble(year = YEARS) |>
  mutate(obs_yr        = sapply(year, function(y) max(staffing_obs$cal_year[staffing_obs$cal_year <= y])),
         staffing_real = staffing_obs$staffing_real[match(obs_yr, staffing_obs$cal_year)])

d_prof <- tibble(year = YEARS) |>
  left_join(career_annual   |> select(year, career_pct),   by = "year") |>
  left_join(spads_annual    |> select(year, n_spads),       by = "year") |>
  left_join(staffing_annual |> select(year, staffing_real), by = "year") |>
  mutate(career_norm   = norm01(career_pct),
         spads_norm    = norm01(n_spads),
         staffing_norm = norm01(staffing_real))

pca_res <- prcomp(d_prof |> select(career_norm, spads_norm, staffing_norm),
                  scale. = TRUE, center = TRUE)
d_prof <- d_prof |> mutate(prof_pc1 = pca_res$x[, 1])
varexp <- round(summary(pca_res)$importance[2, 1] * 100, 1)
cat("PC1 variance explained:", varexp, "%\n")

cor_mat <- cor(d_prof[, c("career_norm", "spads_norm", "staffing_norm")], use = "complete.obs")

# ============================================================
# 1b. CHOW ON PC1 — same method as 41e_professionalisation_pca.R
# ============================================================
d_prof <- d_prof |> mutate(t = year - min(year))
mod_r  <- lm(prof_pc1 ~ t, data = d_prof)
RSS_r  <- sum(resid(mod_r)^2)
n_chow <- nrow(d_prof)
years_sorted     <- sort(d_prof$year)
candidate_breaks <- years_sorted[3:(length(years_sorted) - 3)]
chow_results <- do.call(rbind, lapply(candidate_breaks, function(k) {
  dat1 <- d_prof |> filter(year <= k); dat2 <- d_prof |> filter(year > k)
  if (nrow(dat1) < 3 || nrow(dat2) < 3) return(NULL)
  rss1 <- sum(resid(lm(prof_pc1 ~ t, data = dat1))^2)
  rss2 <- sum(resid(lm(prof_pc1 ~ t, data = dat2))^2)
  F_stat <- ((RSS_r - (rss1 + rss2)) / 2) / ((rss1 + rss2) / (n_chow - 5))
  data.frame(break_year = k, F_stat = max(F_stat, 0))
}))
F_crit <- qf(0.95, df1 = 2, df2 = n_chow - 5)
top10  <- chow_results |> arrange(desc(F_stat)) |> head(10)
cat("\nChow on PC1 (N=", n_chow, ", critical F=", round(F_crit, 2), "):\n", sep = "")
print(top10)

# ============================================================
# 2. FOUR STACKED PANELS — house style
# ============================================================
CANVAS_W <- house_width_in()
XB <- scale_x_continuous(breaks = seq(1980, 2020, 10), limits = c(1979, 2025))
base <- house_print(CANVAS_W)

p1 <- ggplot(d_prof, aes(year, career_pct)) +
  geom_line(colour = "#000000", linewidth = 1.0) +
  XB + labs(tag = "A", subtitle = "Career politicians (% of MPs)", x = NULL, y = "%") +
  base + theme(axis.text.x = element_blank())

p2 <- ggplot(d_prof, aes(year, n_spads)) +
  geom_line(colour = "#000000", linewidth = 1.0) +
  XB + labs(tag = "B", subtitle = "Special advisers (SPADs) in post", x = NULL, y = "n") +
  base + theme(axis.text.x = element_blank())

p3 <- ggplot(d_prof, aes(year, staffing_real / 1000)) +
  geom_line(colour = "#000000", linewidth = 1.0) +
  XB + labs(tag = "C", subtitle = "MP staffing spend, real terms (2015 prices)", x = NULL, y = "£k") +
  base + theme(axis.text.x = element_blank())

p4 <- ggplot(d_prof, aes(year, prof_pc1)) +
  geom_hline(yintercept = 0, colour = "grey85") +
  geom_line(colour = "#000000", linewidth = 1.0) +
  XB + labs(tag = "D", subtitle = "Composite index (PC1)", x = NULL, y = "PC1 (SD)") +
  base

fig <- (p1 / p2 / p3 / p4) +
  plot_annotation(
    title = "Figure 3.5: Professionalisation of the political class, 1979–2025",
    theme = theme(plot.title = element_text(face = "bold", size = pt_for(PRINTED$title, CANVAS_W)),
                  plot.margin = margin(12, 18, 12, 18))
  )

OUT <- file.path(PROJECT, "figures/fig_3_5_professionalisation_composite.png")
ggsave(OUT, fig, width = CANVAS_W, height = CANVAS_W * 1.35, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")

# ============================================================
# 3. FOOTNOTE NOTES — generated so numbers cannot drift from the figure
# ============================================================
old_placeholder <- read_csv(file.path(PROJECT, "data/raw/staffing_pre2010_modelled.csv"),
                            show_col_types = FALSE)
new_calibrated  <- read_csv(file.path(PROJECT, "data/processed/staffing_pre2010_calibrated_butler.csv"),
                            show_col_types = FALSE)
overlap_ratios <- read_csv(file.path(PROJECT, "data/processed/staffing_calibration_robustness.csv"),
                           show_col_types = FALSE)

anchor_comp <- old_placeholder |>
  transmute(year = cal_year, old = mean_staffing_real_2015) |>
  inner_join(new_calibrated |> transmute(year, new = real_2015_mean), by = "year") |>
  mutate(pct_change = round(100 * (new - old) / old, 1))

fmt_top <- function(df, n = 5) {
  paste(sprintf("%d (F=%.2f)", df$break_year[1:n], df$F_stat[1:n]), collapse = ", ")
}

notes <- c(
